css:
:root.theme-ext-theme-notecard-desk {
  --bg: #f7f3eb;
  --bg-secondary: #f0e9dd;
  --bg-surface: #fdfaf4;
  --bg-surface-2: #f4efe4;
  --text: #2b2a28;
  --text-muted: #5c5446;
  --accent: #d07a22;
  --accent-strong: #c15f0d;
  --border: #d9d1c3;
  --shadow-soft: 0 12px 35px rgba(56, 41, 22, 0.22);
  --card-radius: 16px;
  --card-line: rgba(64, 89, 129, 0.22);
}
.theme-ext-theme-notecard-desk body {
  background: radial-gradient(circle at 20% 20%, rgba(255,255,255,0.35), transparent 35%),
              radial-gradient(circle at 70% 30%, rgba(255,255,255,0.2), transparent 30%),
              #e5d7c3;
  color: var(--text);
}
.theme-ext-theme-notecard-desk header {
  background: linear-gradient(135deg, rgba(255,255,255,0.6), rgba(255,255,255,0.25));
  backdrop-filter: blur(6px);
  border-bottom: 1px solid var(--border);
}
.theme-ext-theme-notecard-desk .card {
  background: linear-gradient(var(--card-line) 1px, transparent 1px) 0 18px/100% 30px,
              linear-gradient(to right, rgba(219, 102, 53, 0.18) 48px, transparent 48px),
              var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--card-radius);
  box-shadow: var(--shadow-soft);
  position: relative;
  overflow: hidden;
}
.theme-ext-theme-notecard-desk .card::before {
  content: '';
  position: absolute;
  top: 12px;
  left: 16px;
  width: 16px;
  height: 16px;
  background: radial-gradient(circle at 50% 45%, #fdf5e6 45%, #d08c43 50%, #b9711f 70%);
  border-radius: 50%;
  box-shadow: 18px 6px 0 -4px rgba(0,0,0,0.18);
  opacity: 0.9;
}
.theme-ext-theme-notecard-desk .card:hover {
  transform: translateY(-3px) rotate(-0.2deg);
  box-shadow: 0 16px 50px rgba(0,0,0,0.16);
}
.theme-ext-theme-notecard-desk .card-title {
  color: var(--text);
  font-family: 'Inter', 'SF Pro Text', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.01em;
}
.theme-ext-theme-notecard-desk .btn-primary {
  background: var(--accent);
  border-color: var(--accent-strong);
  box-shadow: 0 8px 18px rgba(209, 122, 34, 0.28);
}
.theme-ext-theme-notecard-desk .btn-primary:hover {
  background: var(--accent-strong);
}
.theme-ext-theme-notecard-desk .card.dark-mode {
  --bg-surface: #1f1b17;
  --bg-surface-2: #221d17;
  --text: #f3ecde;
  --text-muted: #b5a895;
  --border: #3b3126;
  --card-line: rgba(105, 143, 199, 0.3);
  background: linear-gradient(var(--card-line) 1px, transparent 1px) 0 18px/100% 30px,
              linear-gradient(to right, rgba(105, 143, 199, 0.3) 48px, transparent 48px),
              var(--bg-surface);
  box-shadow: 0 14px 40px rgba(0,0,0,0.35);
}
